using System;
using System.Linq;
using Enterprise.ZArchitecture.Environment.Testing;
using NUnit.Framework;

namespace Enterprise.Registry.Business.Testing
{
	[TestedType(typeof(ExportStatementSettingRegistryDataType))]
	sealed class ExportStatementSettingRegistryDataTypeTest : NonPersistentBusinessObjectRegistryDataTypeTestCase<ExportStatementSettingRegistryDataType>
	{
		protected override string ExpectedEditorName
		{
			get { return "ExportStatementSettingRegistryItemEditor"; }
		}

		protected override ExportStatementSettingRegistryDataType GetNewDataType()
		{
			return new ExportStatementSettingRegistryDataType();
		}

		protected override ValidSampleAndBinaryValueInDB[] GetValidSamples()
		{
			CountryExportStatementSettingCollection collection = new CountryExportStatementSettingCollection();
			CountryExportStatementSetting setting = collection.AddNew();
			setting.FillWithValidTestData();

			var bytes = Enumerable.Range(0, HexData.Length)
				.Where(x => x % 2 == 0)
				.Select(x => Convert.ToByte(HexData.Substring(x, 2), 16))
				.ToArray();

			return new ValidSampleAndBinaryValueInDB[]
			{
				new ValidSampleAndBinaryValueInDB(collection, bytes)
			};
		}

		const string HexData =
			"";
	}
}
